-- finance_seed.sql
-- Pre-aggregated Spanberger campaign finance data
-- Generated from Virginia SBE va_cf_schedule_a (local polls.db)
-- Seeded at startup by _finance_seed_task() in main.py
-- DO NOT EDIT BY HAND — regenerate with generate_finance_seed.py

-- ── Cycle totals ─────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS va_finance_cycle_totals (
    candidate_name     TEXT,
    election_cycle     TEXT,
    total              REAL,
    records            INTEGER,
    unique_individuals INTEGER,
    latest_date        TEXT,
    PRIMARY KEY (candidate_name, election_cycle)
);
DELETE FROM va_finance_cycle_totals
  WHERE lower(candidate_name) LIKE '%spanberger%';


-- ── Top donors per cycle ─────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS va_finance_top_donors (
    candidate_name TEXT,
    election_cycle TEXT,
    rank           INTEGER,
    donor_name     TEXT,
    employer       TEXT,
    occupation     TEXT,
    is_individual  INTEGER,
    total          REAL,
    records        INTEGER,
    PRIMARY KEY (candidate_name, election_cycle, rank)
);
DELETE FROM va_finance_top_donors
  WHERE lower(candidate_name) LIKE '%spanberger%';


-- ── Sector totals per cycle ──────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS va_finance_sector_totals (
    candidate_name TEXT,
    election_cycle TEXT,
    sector         TEXT,
    total          REAL,
    records        INTEGER,
    PRIMARY KEY (candidate_name, election_cycle, sector)
);
DELETE FROM va_finance_sector_totals
  WHERE lower(candidate_name) LIKE '%spanberger%';


-- ── campaign_finance_summary (VA legislator finance totals, 109 rows) ─────────
CREATE TABLE IF NOT EXISTS campaign_finance_summary (
            id               INTEGER PRIMARY KEY AUTOINCREMENT,
            legislator_id    TEXT NOT NULL,
            name             TEXT,
            chamber          TEXT,
            district         TEXT,
            party            TEXT,
            source           TEXT,          -- 'fec' or 'va_sbe'
            latest_cycle     TEXT,
            total_raised     REAL DEFAULT 0,
            top_sector       TEXT,
            top_sector_pct   REAL,
            by_sector_json   TEXT,          -- JSON array [{sector, total, donor_count, avg_donation}]
            top_donors_json  TEXT,          -- JSON array [{contributor_name, employer, sector, total, count}]
            cycles_json      TEXT,          -- JSON array of cycle strings
            updated_at       TEXT,
            UNIQUE(legislator_id, source)
        );
DELETE FROM campaign_finance_summary;

